//! Norwegian layout keycodes, ported from the ZMK `keys_nb.h` / `keys_nb_mac.h`
//! headers (generated by zmk-locale-generator). Only the symbols the keymap
//! uses are listed. The host must be set to the Norwegian layout.

use rmk::types::action::{Action, KeyAction};
use rmk::types::keycode::{HidKeyCode, KeyCode};
use rmk::types::modifier::ModifierCombination;

const SHIFT: ModifierCombination = ModifierCombination::LSHIFT;
const ALTGR: ModifierCombination = ModifierCombination::RALT;
const ALT: ModifierCombination = ModifierCombination::LALT;
const SHIFT_ALT: ModifierCombination = ModifierCombination::LSHIFT.with_left_alt(true);

const fn key(k: HidKeyCode) -> KeyAction {
    KeyAction::Single(Action::Key(KeyCode::Hid(k)))
}

const fn with(k: HidKeyCode, m: ModifierCombination) -> KeyAction {
    KeyAction::Single(Action::KeyWithModifier(k, m))
}

/// Norwegian (Windows/Linux), `NB_*` in ZMK
pub mod win {
    use super::*;

    pub const A_RING: KeyAction = key(HidKeyCode::LeftBracket);
    pub const AE: KeyAction = key(HidKeyCode::Quote);
    pub const O_SLASH: KeyAction = key(HidKeyCode::Semicolon);
    pub const PLUS: KeyAction = key(HidKeyCode::Minus);
    pub const MINUS: KeyAction = key(HidKeyCode::Slash);
    pub const APOS: KeyAction = key(HidKeyCode::Backslash);
    pub const PIPE: KeyAction = key(HidKeyCode::Grave);
    pub const BSLH: KeyAction = key(HidKeyCode::Equal);
    pub const LT: KeyAction = key(HidKeyCode::NonusBackslash);
    pub const GT: KeyAction = with(HidKeyCode::NonusBackslash, SHIFT);
    pub const EXCL: KeyAction = with(HidKeyCode::Kc1, SHIFT);
    pub const HASH: KeyAction = with(HidKeyCode::Kc3, SHIFT);
    pub const LPAR: KeyAction = with(HidKeyCode::Kc8, SHIFT);
    pub const RPAR: KeyAction = with(HidKeyCode::Kc9, SHIFT);
    pub const EQUAL: KeyAction = with(HidKeyCode::Kc0, SHIFT);
    pub const ASTRK: KeyAction = with(HidKeyCode::Backslash, SHIFT);
    pub const CARET: KeyAction = with(HidKeyCode::RightBracket, SHIFT);
    pub const SEMI: KeyAction = with(HidKeyCode::Comma, SHIFT);
    pub const COLON: KeyAction = with(HidKeyCode::Dot, SHIFT);
    pub const AT: KeyAction = with(HidKeyCode::Kc2, ALTGR);
    pub const LBRC: KeyAction = with(HidKeyCode::Kc7, ALTGR);
    pub const RBRC: KeyAction = with(HidKeyCode::Kc0, ALTGR);
    pub const LBKT: KeyAction = with(HidKeyCode::Kc8, ALTGR);
    pub const RBKT: KeyAction = with(HidKeyCode::Kc9, ALTGR);
    pub const TILDE: KeyAction = with(HidKeyCode::RightBracket, ALTGR);
    pub const ACUTE: KeyAction = with(HidKeyCode::Equal, ALTGR);
}

/// Norwegian (macOS), `NBM_*` in ZMK
pub mod mac {
    use super::*;

    pub const A_RING: KeyAction = key(HidKeyCode::LeftBracket);
    pub const AE: KeyAction = key(HidKeyCode::Quote);
    pub const O_SLASH: KeyAction = key(HidKeyCode::Semicolon);
    pub const PLUS: KeyAction = key(HidKeyCode::Minus);
    pub const MINUS: KeyAction = key(HidKeyCode::Slash);
    pub const APOS: KeyAction = key(HidKeyCode::NonusBackslash);
    pub const AT: KeyAction = key(HidKeyCode::Backslash);
    pub const LT: KeyAction = key(HidKeyCode::Grave);
    pub const ACUTE: KeyAction = key(HidKeyCode::Equal);
    pub const GT: KeyAction = with(HidKeyCode::Grave, SHIFT);
    pub const EXCL: KeyAction = with(HidKeyCode::Kc1, SHIFT);
    pub const HASH: KeyAction = with(HidKeyCode::Kc3, SHIFT);
    pub const LPAR: KeyAction = with(HidKeyCode::Kc8, SHIFT);
    pub const RPAR: KeyAction = with(HidKeyCode::Kc9, SHIFT);
    pub const EQUAL: KeyAction = with(HidKeyCode::Kc0, SHIFT);
    pub const ASTRK: KeyAction = with(HidKeyCode::Backslash, SHIFT);
    pub const SEMI: KeyAction = with(HidKeyCode::Comma, SHIFT);
    pub const COLON: KeyAction = with(HidKeyCode::Dot, SHIFT);
    pub const PIPE: KeyAction = with(HidKeyCode::Kc7, ALT);
    pub const LBKT: KeyAction = with(HidKeyCode::Kc8, ALT);
    pub const RBKT: KeyAction = with(HidKeyCode::Kc9, ALT);
    pub const TILDE: KeyAction = with(HidKeyCode::RightBracket, ALT);
    pub const BSLH: KeyAction = with(HidKeyCode::Kc7, SHIFT_ALT);
    pub const LBRC: KeyAction = with(HidKeyCode::Kc8, SHIFT_ALT);
    pub const RBRC: KeyAction = with(HidKeyCode::Kc9, SHIFT_ALT);
    /// ˆ (`NBM_MODIFIER_CIRCUMFLEX`)
    pub const CIRCUMFLEX: KeyAction = with(HidKeyCode::I, SHIFT_ALT);
}
